package com.kgsat.notification.consumer; import com.kgsat.notification.model.PaymentEvent; import org.slf4j.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.kafka.support.Acknowledgment; import org.springframework.stereotype.Component; @Component public class NotificationConsumer { private static final Logger log=LoggerFactory.getLogger(NotificationConsumer.class); @KafkaListener(topics="${app.kafka.payments-topic}",groupId="notification-service") public void consume(PaymentEvent event,Acknowledgment ack){log.info("event=notification_sent orderId={} customerId={} status={}",event.orderId(),event.customerId(),event.status());ack.acknowledge();} }
